// Leest alle rijen uit de log-sheet en berekent de dashboard-statistieken.
// Gebruikt de echte kolomnamen uit tabblad "Verwerkte facturen".

const rows = $input.all().map(i => i.json);

// Helper: zet een sheet-waarde veilig om naar een getal.
// Vangt zowel "1234.56" als "1.234,56" (NL-notatie) op.
function num(v) {
  if (v == null || v === '') return 0;
  if (typeof v === 'number') return v;
  let s = String(v).trim();
  if (s.includes(',') && s.includes('.')) {
    s = s.replace(/\./g, '').replace(',', '.');      // 1.234,56 -> 1234.56
  } else if (s.includes(',')) {
    s = s.replace(',', '.');                          // 1234,56  -> 1234.56
  }
  const n = parseFloat(s.replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}

const stats = {
  aantalFacturen: rows.length,
  totaalBedrag: 0,
  totaalBtw: 0,
  totaalBetaalbaar: 0,
  aantalPass: 0,
  aantalReview: 0,
  aantalFatal: 0,
  leveranciers: new Set(),
  recenteFacturen: []
};

for (const r of rows) {
  stats.totaalBedrag     += num(r.totaalbedrag);
  stats.totaalBtw        += num(r.btwbedrag);
  stats.totaalBetaalbaar += num(r.betaalbaarBedrag);

  const res = String(r.validatieResultaat || '').toUpperCase();
  if (res === 'PASS')        stats.aantalPass++;
  else if (res === 'REVIEW') stats.aantalReview++;
  else if (res === 'FATAL')  stats.aantalFatal++;

  if (r.leveranciernaam) stats.leveranciers.add(r.leveranciernaam);
}

stats.aantalLeveranciers = stats.leveranciers.size;
delete stats.leveranciers;

// Laatste 15 facturen, nieuwste bovenaan (sheet voegt onderaan toe)
stats.recenteFacturen = rows.slice(-15).reverse().map(r => ({
  factuurnummer:      r.factuurnummer || '-',
  leveranciernaam:    r.leveranciernaam || '-',
  factuurdatum:       r.factuurdatum || '-',
  totaalbedrag:       num(r.totaalbedrag),
  validatieResultaat: String(r.validatieResultaat || 'onbekend').toUpperCase()
}));

return [{ json: stats }];

const s = $input.first().json;
const eur = n => '\u20ac ' + Number(n || 0).toLocaleString('nl-NL', {minimumFractionDigits: 2, maximumFractionDigits: 2});

const statusKleur = {
  PASS:   'background:#e1f5ee;color:#0f6e56;',
  REVIEW: 'background:#faeeda;color:#854f0b;',
  FATAL:  'background:#fcebeb;color:#a32d2d;'
};
const statusLabel = { PASS: 'Goedgekeurd', REVIEW: 'Review', FATAL: 'Actie nodig' };

// KPI-kaart als tabelcel (mail-veilig, geen grid)
function kpi(label, waarde, kleur) {
  return `<td width="25%" style="padding:8px">
    <table width="100%" cellpadding="0" cellspacing="0" style="background:#f7fafc;border-radius:8px">
      <tr><td style="padding:14px;text-align:center">
        <div style="font-size:11px;color:#718096;text-transform:uppercase;letter-spacing:0.5px">${label}</div>
        <div style="font-size:22px;font-weight:700;color:${kleur || '#1a202c'};margin-top:4px">${waarde}</div>
      </td></tr>
    </table>
  </td>`;
}

const rijen = s.recenteFacturen.map(f => {
  const kleur = statusKleur[f.validatieResultaat] || 'background:#f1efe8;color:#5f5e5a;';
  const label = statusLabel[f.validatieResultaat] || f.validatieResultaat;
  return `<tr>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;font-family:monospace;font-size:13px">${f.factuurnummer}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px">${f.leveranciernaam}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;font-size:13px">${f.factuurdatum}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7;text-align:right;font-size:13px">${eur(f.totaalbedrag)}</td>
    <td style="padding:8px;border-bottom:1px solid #edf2f7"><span style="${kleur}padding:2px 10px;border-radius:99px;font-size:12px;font-weight:500">${label}</span></td>
  </tr>`;
}).join('');

const html = `<table width="100%" cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;background:#f5f7fa;padding:20px">
<tr><td align="center">
<table width="700" cellpadding="0" cellspacing="0" style="background:white;border-radius:12px;overflow:hidden">
  <tr><td style="background:#1e3c72;padding:24px 28px">
    <div style="color:white;font-size:22px;font-weight:700">Inkoopfacturatie dashboard</div>
    <div style="color:#cbd5e0;font-size:14px;margin-top:4px">Bajo Bouw &middot; overzicht verwerkte facturen</div>
  </td></tr>
  <tr><td style="padding:16px 20px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Totaal', s.aantalFacturen, '#1a202c')}
      ${kpi('Goedgekeurd', s.aantalPass, '#0f6e56')}
      ${kpi('Review', s.aantalReview, '#854f0b')}
      ${kpi('Actie nodig', s.aantalFatal, '#a32d2d')}
    </tr><tr>
      ${kpi('Leveranciers', s.aantalLeveranciers, '#1a202c')}
      ${kpi('Totaal incl. BTW', eur(s.totaalBedrag), '#1a202c')}
      ${kpi('Totaal BTW', eur(s.totaalBtw), '#1a202c')}
      ${kpi('Te betalen', eur(s.totaalBetaalbaar), '#1a202c')}
    </tr></table>
  </td></tr>
  <tr><td style="padding:8px 28px 28px">
    <div style="font-size:16px;font-weight:600;margin-bottom:12px;color:#1a202c">Recente facturen (laatste 15)</div>
    <table width="100%" cellpadding="0" cellspacing="0">
      <tr>
        <th style="text-align:left;padding:8px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Factuurnr.</th>
        <th style="text-align:left;padding:8px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Leverancier</th>
        <th style="text-align:left;padding:8px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Datum</th>
        <th style="text-align:right;padding:8px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Bedrag</th>
        <th style="text-align:left;padding:8px;border-bottom:2px solid #e2e8f0;font-size:11px;color:#718096;text-transform:uppercase">Status</th>
      </tr>
      ${rijen}
    </table>
  </td></tr>
  <tr><td style="background:#2c3e50;padding:16px;text-align:center;color:#a0aec0;font-size:12px">
    Automatisch gegenereerd op ${new Date().toLocaleString('nl-NL', {timeZone:'Europe/Amsterdam'})}
  </td></tr>
</table>
</td></tr></table>`;

return [{ json: { html } }];
